package com.procurement.service;
import com.procurement.entity.*; import com.procurement.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.*;
@Service public class CatalogService { private final CropRepository crops; private final SeasonRepository seasons; private final CentreRepository centres; private final ScheduleRepository schedules; private final SeasonCropRepository seasonCrops; public CatalogService(CropRepository crops,SeasonRepository seasons,CentreRepository centres,ScheduleRepository schedules,SeasonCropRepository seasonCrops){this.crops=crops;this.seasons=seasons;this.centres=centres;this.schedules=schedules;this.seasonCrops=seasonCrops;}
 public List<Crop> crops(){return crops.findByActiveTrue();} public List<ProcurementSeason> seasons(){return seasons.findByActiveTrue();} public List<ProcurementCentre> centres(){return centres.findByActiveTrue();} public ProcurementCentre centre(Long id){return centres.findById(id).orElseThrow(()->new NoSuchElementException("Centre not found"));}
 public List<Crop> seasonCrops(Long id){return seasonCrops.findActiveCropsBySeasonId(id);} public List<ProcurementSchedule> schedules(Long centreId,Long cropId,LocalDate date){ if(centreId!=null)return schedules.findByCentreId(centreId); if(cropId!=null)return schedules.findByCropId(cropId); if(date!=null)return schedules.findByScheduleDate(date); return schedules.findByStatusAndScheduleDateGreaterThanEqual(ScheduleStatus.OPEN,LocalDate.now()); }
}
